head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldstf07430";

// TODO Stage2: 컨텍스트 키 출처 미확인(as-is EL · 회신 A-3) — param.listTpClssCd

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        await scwin.init_rowCopy();
        scwin.init_attrReals();
        scwin.init_conds();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldstf07430.onpageload' });
    }
};

/**
 * @method
 * @name init_attrReals
 * @description 속성 실현 — as-is EL 이 그리던 안내 문구·속성을 컨텍스트 값으로 반영(진입 1회·데이터 재적재 시 재호출)
 * @returns {void}
 * @hidden N
 */
scwin.init_attrReals = function () {
    const attrRealsList = [{ childId: "txa_majshrhdContn", attr: "label", fn: function () { return String(dma_comInfo.get("majshrhdContn")); } },
        { childId: "txa_remk", attr: "label", fn: function () { return String(dma_comInfo.get("remk")); } }];
    attrRealsList.forEach(function (a) {
        const comp = $c.util.getComponent(a.childId);
        if (!comp) { return; }
        let v;
        try { v = a.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "attrReal:" + a.childId }); return; }
        if (a.attr === "style") {
            String(v).split(";").forEach(function (decl) {
                const kv = decl.split(":");
                if (kv.length === 2 && kv[0].trim()) { comp.setStyle(kv[0].trim(), kv[1].trim()); }
            });
        } else if (a.attr === "label" || a.attr === "__value") {
            if (typeof comp.setValue === "function") { comp.setValue(v); } else if (comp.render) { comp.render.textContent = v; }
        } else if (a.attr === "__items") {
            if (typeof comp.addItem === "function" && v && v.length) {
                if (typeof comp.removeAll === "function") { comp.removeAll(); }
                v.forEach(function (it) { comp.addItem(String(it[0] || ""), String(it[1] || "")); });
            }
        } else if (a.attr === "class") {
            if (comp.render) { comp.render.className = v; }
        } else if (a.attr === "__html") {
            if (comp.render) { comp.render.innerHTML = v; }
        } else if (comp.render) {
            comp.render.setAttribute(a.attr, v);
        }
    });
};

/**
 * @method
 * @name init_conds
 * @description 표시 조건 평가 — 컨텍스트·세션 값에 따라 영역·버튼을 show/hide(진입 1회·데이터 재적재 시 재호출)
 * @returns {void}
 * @hidden N
 */
scwin.init_conds = function () {
    const binds = [{ id: "if_acntclsMmdd1", fn: function(){ return ((dma_comInfo.get("acntclsMmdd1") ?? (() => { throw new Error("unresolved:" + "comInfo.acntclsMmdd1"); })()) !== ''); } }, { id: "if_secugrpId", fn: function(){ return ((dma_comInfo.get("secugrpId") ?? (() => { throw new Error("unresolved:" + "comInfo.secugrpId"); })()) !=='RT'); } }, { id: "if_secugrpId_2", fn: function(){ return ((dma_comInfo.get("secugrpId") ?? (() => { throw new Error("unresolved:" + "comInfo.secugrpId"); })()) ==='FS'); } }, { id: "if_secugrpId_3", fn: function(){ return ((dma_comInfo.get("secugrpId") ?? (() => { throw new Error("unresolved:" + "comInfo.secugrpId"); })()) === 'DR'); } }, { id: "if_exstStrtDd", fn: function(){ return ((dma_comInfo.get("exstStrtDd") ?? (() => { throw new Error("unresolved:" + "comInfo.exstStrtDd"); })()) !== ''); } }, { id: "if_exstEndDd", fn: function(){ return ((dma_comInfo.get("exstEndDd") ?? (() => { throw new Error("unresolved:" + "comInfo.exstEndDd"); })()) !== ''); } }, { id: "if_acntclsMmdd1_2", fn: function(){ return ((dma_comInfo.get("acntclsMmdd1") ?? (() => { throw new Error("unresolved:" + "comInfo.acntclsMmdd1"); })()) !== ''); } }, { id: "if_acntclsMmdd2", fn: function(){ return ((dma_comInfo.get("acntclsMmdd2") ?? (() => { throw new Error("unresolved:" + "comInfo.acntclsMmdd2"); })()) !== ''); } }, { id: "if_acntclsMmdd3", fn: function(){ return ((dma_comInfo.get("acntclsMmdd3") ?? (() => { throw new Error("unresolved:" + "comInfo.acntclsMmdd3"); })()) !== ''); } }, { id: "if_acntclsMmdd4", fn: function(){ return ((dma_comInfo.get("acntclsMmdd4") ?? (() => { throw new Error("unresolved:" + "comInfo.acntclsMmdd4"); })()) !== ''); } }, { id: "if_secugrpId_4", fn: function(){ return ((dma_comInfo.get("secugrpId") ?? (() => { throw new Error("unresolved:" + "comInfo.secugrpId"); })()) === 'RT'); } }, { id: "if_listTpClssCd_3", fn: function(){ return ((dma_pageContext.get("listTpClssCd") ?? "") ==='06' ||  (dma_pageContext.get("listTpClssCd") ?? "") ==='02'); } }];
    binds.forEach(function (b) {
        const comp = $c.util.getComponent(b.id);
        if (!comp) { return; }
        let ok;
        // 조건식이 미해결 값(unresolved throw)을 읽는 자리는 그 바인드만 건너뛴다 — 공급사 산출의 바인드별 격리 유지
        try { ok = !!b.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "conds:" + b.id }); return; }
        if (ok) { comp.show(); } else { comp.hide(); }
        if (ok && b.grids) {
            b.grids.forEach(function (gid) {
                const gc = $c.util.getComponent(gid);
                if (gc && gc.refreshGridView) { gc.refreshGridView(); }
            });
        }
    });
};

/**
 * @method
 * @name init_rowCopy
 * @description dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init_rowCopy = async function () {
    const rows = [{ childId: "__rb3", fn: function () { return String(dma_comInfo.get("ventStrtYymm")) + " ~ " + String(dma_comInfo.get("ventEndYymm")); } },
        { childId: "__rb4", fn: function () { return String(dma_comInfo.get("innoBizAhthStrtYymm")) + " ~ " + String(dma_comInfo.get("innoBizAhthEndYymm")); } }];
    let copied = 0;
    for (let i = 0; i < rows.length; i++) {
        const it = rows[i];
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { /* TODO Stage2: [sdd] 행 복사 대상 부재:  it.childId */ continue; }
        try {
            const v = it.fn();
            if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); copied++; }
        } catch (e) { await $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); }
    }
    return copied;
};

// [A] 초기 목록 미해결 — jldstf07430: 열자마자 목록을 채울 근거가 없다(진입 URL 0 · 자기 목록 tx 0 · 화면 자신의 액션 URL 도 못 가름)

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name btn_print_onclick
 * @description btn_print 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_print_onclick = function(e){
    try {
        fn_print()

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldstf07430.btn_print_onclick' }); }
};

/**
 * @method
 * @name grd_leadcomList_oncellclick
 * @description grd_leadcomList 셀 클릭 이벤트
 * @param {Number} rowIndex 행 인덱스
 * @param {Number} columnIndex 열 인덱스
 * @param {String} columnId 컬럼 id
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_leadcomList_oncellclick = async function (rowIndex, columnIndex, columnId) {
    try {
        const dl = $c.util.getComponent('dlt_leadcomList');
        if (!dl) { /* TODO Stage2: [sdd] 행 동작 대상 목록 없음: dlt_leadcomList */ return; }
        const r = dl.getRowJSON ? dl.getRowJSON(rowIndex) : null;
        if (!r) { return; }
        await scwin.openInfoWin1(); return;
    } catch (e) {
        await $c.exception.handleError(e, { notify: 'none', context: 'grd_leadcomList.oncellclick' });
    }
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name openInfoWin1
 * @description open Info Win1 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.openInfoWin1 = async function () {
    const infoWin = {};
    const url = "/jldfil55300_1/jldfil55300_1.xml";
    const style = "dialogWidth:580px;dialogHeight:200px;scroll:no;resize:no";
    // TODO Stage2: 전환 미완(공급사 드러냄 — 사유 알림 유지) "이 화면의 이동 목적지를 아직 정하지 못했습니다(전환 미완) — "
    Object.assign(infoWin, (await $c.win.openPopup((function (__u) { let __s = String(__u == null ? "" : __u); if (!/\.xml(\?|#|$)/.test(__s)) { throw { bizMessage: "이 화면의 이동 목적지를 아직 정하지 못했습니다(전환 미완) — " + __s, unresolved: "nav:" + __s }; } return __u; })(url), { type: 'pageFramePopup', modal: true }, infoWin)) || {});
};

/**
 * @method
 * @name openInfoWin2
 * @description open Info Win2 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.openInfoWin2 = async function () {
    const infoWin = {};
    const url = "/jldfil55300_2/jldfil55300_2.xml";
    const style = "dialogWidth:580px;dialogHeight:200px;scroll:no;resize:no";
    // TODO Stage2: 전환 미완(공급사 드러냄 — 사유 알림 유지) "이 화면의 이동 목적지를 아직 정하지 못했습니다(전환 미완) — "
    Object.assign(infoWin, (await $c.win.openPopup((function (__u) { let __s = String(__u == null ? "" : __u); if (!/\.xml(\?|#|$)/.test(__s)) { throw { bizMessage: "이 화면의 이동 목적지를 아직 정하지 못했습니다(전환 미완) — " + __s, unresolved: "nav:" + __s }; } return __u; })(url), { type: 'pageFramePopup', modal: true }, infoWin)) || {});
};
